function createSearch(showResults, showError) {
  let controller = null;                               // the in-flight request.

  return async function search(query) {
    controller?.abort();                               // cancel the previous search.
    controller = new AbortController();
    const { signal } = controller;
    try {
      const response = await fetch(`/api/search?q=${encodeURIComponent(query)}`, { signal });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      showResults(await response.json());
    } catch (error) {
      if (error.name === "AbortError") return;       // intentional: stay quiet.
      showError("Search failed. Try again.");          // real failure: report it.
    }
  };
}

const search = createSearch(renderList, renderError);
input.addEventListener("input", () => search(input.value));
